package com.nunnun.roommate.service;
import com.nunnun.global.exception.*; import com.nunnun.user.entity.User; import com.nunnun.user.repository.UserRepository; import com.nunnun.wake.service.InviteCodeGenerator; import com.nunnun.roommate.entity.*; import com.nunnun.roommate.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RoommateGroupService { private final RoommateGroupRepository groups; private final RoommateGroupMemberRepository members; private final UserRepository users; private final InviteCodeGenerator codes; public RoommateGroupService(RoommateGroupRepository g,RoommateGroupMemberRepository m,UserRepository u,InviteCodeGenerator c){groups=g;members=m;users=u;codes=c;} @Transactional public RoommateGroup create(Long uid,String name){User u=user(uid); ensureFree(uid); RoommateGroup g=groups.save(RoommateGroup.create(name,code(),u)); members.save(RoommateGroupMember.join(g,u,(short)1)); return g;} @Transactional public RoommateGroup join(Long uid,String code){User u=user(uid);ensureFree(uid);RoommateGroup g=groups.findByInviteCodeForUpdate(code).orElseThrow(()->new BusinessException(ErrorCode.ROOMMATE_GROUP_NOT_FOUND));if(g.getStatus()!=RoommateGroupStatus.WAITING||members.countByRoommateGroupId(g.getId())!=1)throw new BusinessException(ErrorCode.ROOMMATE_GROUP_FULL);short slot=members.findAllByRoommateGroupId(g.getId()).stream().anyMatch(m->m.getSlotNo()==1)?(short)2:(short)1;members.save(RoommateGroupMember.join(g,u,slot));g.activate();return g;} @Transactional public void leave(Long uid,Long gid){RoommateGroupMember m=members.findByRoommateGroupIdAndUserId(gid,uid).orElseThrow(()->new BusinessException(ErrorCode.ROOMMATE_GROUP_MEMBER_NOT_FOUND));RoommateGroup g=m.getRoommateGroup();members.delete(m);if(members.countByRoommateGroupId(gid)==1)g.waitForRoommate();else if(members.countByRoommateGroupId(gid)==0)groups.delete(g);} @Transactional(readOnly=true) public String invite(Long uid,Long gid){if(!members.existsByRoommateGroupIdAndUserId(gid,uid))throw new BusinessException(ErrorCode.FORBIDDEN);return groups.findById(gid).orElseThrow(()->new BusinessException(ErrorCode.ROOMMATE_GROUP_NOT_FOUND)).getInviteCode();} private User user(Long id){return users.findByIdAndDeletedAtIsNull(id).orElseThrow(()->new BusinessException(ErrorCode.USER_NOT_FOUND));} private void ensureFree(Long id){if(members.existsByUserId(id))throw new BusinessException(ErrorCode.ROOMMATE_GROUP_ALREADY_EXISTS);} private String code(){for(int i=0;i<5;i++){String c=codes.generate();if(!groups.existsByInviteCode(c))return c;}throw new BusinessException(ErrorCode.INVITE_CODE_GENERATION_FAILED);} }
